import { logger, router } from '#prewire'

/**
 * A consumer living INSIDE the shared kit. It imports '#prewire' exactly
 * like app code does — kit never depends on app packages, yet each app's
 * build wires this very module to that app's own composition root
 * (per-app tsconfig paths / bundler alias generated by codegen).
 */
export function shareLink(path: string): string {
  const href = router.href(path)
  logger.info(`[kit] share link built: ${href}`)
  return href
}

export function openShared(path: string): void {
  logger.info(`[kit] opening shared path: ${path}`)
  router.push(path)
}
